#!/usr/bin/env python3
"""Generates app/multi_bootstrap_css.h (Bootstrap's CSS as a C++ string the multi-channel receiver serves at /assets/bootstrap.css, so the page
works offline) from third_party/bootstrap/bootstrap.min.css. Run from the project root: python tools/gen_multi_bootstrap.py"""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
css = (root / "third_party/bootstrap/bootstrap.min.css").read_text(encoding="utf-8")
css = re.sub(r"/\*# sourceMappingURL=.*?\*/", "", css).strip()
delim = ")BS5CSS\""
assert delim not in css
out = root / "app/multi_bootstrap_css.h"
out.write_text('// Generated by tools/gen_multi_bootstrap.py from third_party/bootstrap (Bootstrap 5.3.3, MIT licence).\n'
               '#pragma once\ninline constexpr const char* multiBootstrapCss = R"BS5CSS(' + css + ')BS5CSS";\n', encoding="utf-8")
print(out, len(css), "bytes of CSS")
